def hidden_rule_fn(state):
    n = len(state)
    next_state = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            # Get diagonal neighbors with toroidal wrap
            diagonals = [
                state[(r-1)%n][(c+1)%n],  # NE
                state[(r-1)%n][(c-1)%n],  # NW
                state[(r+1)%n][(c+1)%n],  # SE
                state[(r+1)%n][(c-1)%n]   # SW
            ]
            d_z = diagonals.count(0)
            d_p = diagonals.count(1)
            d_q = diagonals.count(2)
            own = state[r][c]

            # Rule based on diagonal-tetrad counts and own state
            if d_q > d_z:
                if d_p == 0:
                    next_state[r][c] = (2 - own) % 3
                else:
                    next_state[r][c] = own
            else:  # d_z >= d_q
                if d_p == 0:
                    next_state[r][c] = min(own, 1)
                else:
                    next_state[r][c] = (own + d_q) % 3
    return next_state
